"""
Domain Layer Events.
Pure events recorded on aggregate roots for post-commit dispatch.
"""

import time
from typing import Dict, Any

class DomainEvent:
    """Base domain event accepting flexible keyword attributes."""
    def __init__(self, *args, **kwargs):
        self.timestamp = kwargs.get("timestamp", time.time())
        for k, v in kwargs.items():
            setattr(self, k, v)

    def to_dict(self) -> Dict[str, Any]:
        return {k: v for k, v in self.__dict__.items() if not k.startswith("_")}

class MaintenanceRequiredEvent(DomainEvent):
    """Event fired when maintenance is required."""
    pass

class MaintenanceLockedEvent(DomainEvent):
    """Event fired when asset is locked for maintenance."""
    pass

class DifficultyCreatedEvent(DomainEvent):
    pass

class DifficultyUpdatedEvent(DomainEvent):
    pass

class GameSessionCreatedEvent(DomainEvent):
    pass

class GameSessionUpdatedEvent(DomainEvent):
    pass

"""
Repository Layer: Abstract and In-Memory Fake Repositories for DDD entities.
"""

from abc import ABC, abstractmethod
from typing import List, Optional, Dict
from src.domain.difficulty import Difficulty
from src.domain.game_session import GameSession

class AbstractDifficultyRepository(ABC):
    @abstractmethod
    def add(self, item: Difficulty) -> None:
        raise NotImplementedError

    @abstractmethod
    def get(self, item_id: str) -> Optional[Difficulty]:
        raise NotImplementedError

    @abstractmethod
    def list(self) -> List[Difficulty]:
        raise NotImplementedError

    @abstractmethod
    def delete(self, item_id: str) -> None:
        raise NotImplementedError


class AbstractGameSessionRepository(ABC):
    @abstractmethod
    def add(self, item: GameSession) -> None:
        raise NotImplementedError

    @abstractmethod
    def get(self, item_id: str) -> Optional[GameSession]:
        raise NotImplementedError

    @abstractmethod
    def list(self) -> List[GameSession]:
        raise NotImplementedError

    @abstractmethod
    def delete(self, item_id: str) -> None:
        raise NotImplementedError


class FakeDifficultyRepository(AbstractDifficultyRepository):
    def __init__(self, items: Optional[List[Difficulty]] = None):
        self._items: Dict[str, Difficulty] = {getattr(i, 'id', str(idx)): i for idx, i in enumerate(items or [])}

    def add(self, item: Difficulty) -> None:
        self._items[str(getattr(item, 'id', ''))] = item

    def get(self, item_id: str) -> Optional[Difficulty]:
        return self._items.get(str(item_id))

    def list(self) -> List[Difficulty]:
        return list(self._items.values())

    def delete(self, item_id: str) -> None:
        self._items.pop(str(item_id), None)


class FakeGameSessionRepository(AbstractGameSessionRepository):
    def __init__(self, items: Optional[List[GameSession]] = None):
        self._items: Dict[str, GameSession] = {getattr(i, 'id', str(idx)): i for idx, i in enumerate(items or [])}

    def add(self, item: GameSession) -> None:
        self._items[str(getattr(item, 'id', ''))] = item

    def get(self, item_id: str) -> Optional[GameSession]:
        return self._items.get(str(item_id))

    def list(self) -> List[GameSession]:
        return list(self._items.values())

    def delete(self, item_id: str) -> None:
        self._items.pop(str(item_id), None)

"""
Unit of Work Layer: Manages atomic transactional boundaries and repositories.
"""

from abc import ABC, abstractmethod
from src.adapters import repository

class AbstractUnitOfWork(ABC):
    difficulties: repository.AbstractDifficultyRepository
    game_sessions: repository.AbstractGameSessionRepository

    def __enter__(self):
        return self

    def __exit__(self, *args):
        self.rollback()

    def commit(self):
        self._commit()

    @abstractmethod
    def _commit(self):
        raise NotImplementedError

    @abstractmethod
    def rollback(self):
        raise NotImplementedError


class FakeUnitOfWork(AbstractUnitOfWork):
    def __init__(self):
        self.difficulties = repository.FakeDifficultyRepository()
        self.game_sessions = repository.FakeGameSessionRepository()
        self.committed = False

    def _commit(self):
        self.committed = True

    def rollback(self):
        pass

