// A first draft of the app: the records as they are, until the page is written.
const TITLE_FIELD = 'name';
const FORM_FIELDS: { name: string; numeric: boolean }[] = [{ name: 'name', numeric: false }, { name: 'rows', numeric: true }, { name: 'columns', numeric: true }, { name: 'mine_count', numeric: true }];

