export const DifficultyView: React.FC = () => {
  const [items, setItems] = useState<Difficulty[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [adding, setAdding] = useState(false);
  const [formData, setFormData] = useState<Record<string, any>>({});

  const load = async () => {
    try {
      setItems(await fetchDifficultyList());
      setError(null);
    } catch (err: any) {
      setError(err.message || 'Could not load difficulties');
    }
  };

  // The starting content is written a little after the app starts: ask again while there is nothing to show
  const empty = items.length === 0;
  useEffect(() => {
    load();
    if (!empty) return;
    const timer = setInterval(load, 3000);
    return () => clearInterval(timer);
  }, [empty]);

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await createDifficulty(formData);
      setAdding(false);
      setFormData({});
      await load();
    } catch (err: any) {
      setError(err.message || 'Could not save');
    }
  };

  return (
    <section className="max-w-5xl mx-auto px-4 sm:px-6 py-8 space-y-6">
